// A Meta chama esta URL com GET uma vez para confirmar que o webhook é seu
const q = $input.first().json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.WA_VERIFY_TOKEN;
return [{ json: { ok, challenge: q['hub.challenge'] || '' } }];

// Pega a mensagem recebida. Eventos de status (entregue, lido) não têm "messages" e são ignorados.
const body = $input.first().json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg) return [];

const texto = msg.type === 'text'
  ? msg.text.body
  : `[O candidato enviou um(a) ${msg.type}, que o bot ainda não consegue ler. Peça gentilmente para escrever em texto.]`;

return [{ json: {
  from: msg.from,
  nomePerfil: value.contacts?.[0]?.profile?.name || '',
  texto,
} }];

// Monta o contexto para a IA: prompt + vagas + dados do candidato (por enquanto vindos de data/, depois do InHire)
const fs = require('fs');
const item = $input.first().json;

const candidatos = JSON.parse(fs.readFileSync('/files/candidatos.json', 'utf8'));
const vagas = fs.readFileSync('/files/vagas.md', 'utf8');
const prompt = fs.readFileSync('/files/prompt-bot.md', 'utf8');

// Compara só os 8 últimos dígitos: no Brasil o WhatsApp às vezes manda o número sem o 9 extra
const fim8 = (s) => String(s).replace(/\D/g, '').slice(-8);
const candidato = candidatos.find((c) => fim8(c.telefone) === fim8(item.from)) || null;

const system = [
  prompt,
  '# Vagas',
  vagas,
  '# Candidato',
  candidato
    ? JSON.stringify({ nome: candidato.nome, vaga: candidato.vaga, etapa: candidato.etapa }, null, 2)
    : `Número não encontrado na base. Nome no perfil do WhatsApp: ${item.nomePerfil || 'desconhecido'}.`,
].join('\n\n');

return [{ json: { ...item, candidato, system } }];

