// Lê a resposta da IA e prepara o(s) envio(s): resposta ao candidato + alerta para a recrutadora se precisar
const ctx = $('Montar contexto').first().json;
let texto = ($input.first().json.content || [])
  .filter((b) => b.type === 'text')
  .map((b) => b.text)
  .join('\n')
  .trim();

const encaminhar = texto.startsWith('[ENCAMINHAR]');
texto = texto.replace('[ENCAMINHAR]', '').trim() || 'Recebi sua mensagem! Já vou verificar e te retorno.';

const envios = [{ to: ctx.from, type: 'text', text: { body: texto } }];

if (encaminhar && $env.RECRUITER_PHONE) {
  envios.push({
    to: $env.RECRUITER_PHONE,
    type: 'text',
    text: { body: `⚠️ Candidato pediu atendimento humano\nNome: ${ctx.candidato?.nome || ctx.nomePerfil}\nNúmero: ${ctx.from}\nVaga: ${ctx.candidato?.vaga || '-'}\nMensagem: ${ctx.texto}` },
  });
}

return envios.map((e) => ({ json: { messaging_product: 'whatsapp', ...e } }));
